-- 法律法规清单模块 V34：以服务商提供的《适用安全生产法律法规标准清单（整理版）》为初始模板扩充
-- 88 条适用法规，覆盖消防安全/职业健康/地方法规/交通安全/安全与应急/综合要求/教育培训七类。
-- 权限：服务商(provider)/超管(admin) 增删改查；企业(enterprise) 只读 + 下载 PDF。

ALTER TABLE `law_catalog`
    MODIFY COLUMN `effective_date` VARCHAR(40) NOT NULL DEFAULT '' COMMENT '生效/实施日期（可能含「现行修正版」说明）',
    ADD COLUMN `revise_date`   VARCHAR(20)  NOT NULL DEFAULT '' COMMENT '最新修订/修正时间' AFTER `effective_date`,
    ADD COLUMN `apply_level`   VARCHAR(20)  NOT NULL DEFAULT '国家' COMMENT '适用层级：国家/省级/市级' AFTER `law_level`,
    ADD COLUMN `region`        VARCHAR(40)  NOT NULL DEFAULT '全国' COMMENT '适用地区' AFTER `apply_level`,
    ADD COLUMN `biz_type`      VARCHAR(20)  NOT NULL DEFAULT 'all' COMMENT '适用业务：all通用/cargo普货/danger危货' AFTER `apply_scope`,
    ADD COLUMN `is_applicable` VARCHAR(20)  NOT NULL DEFAULT 'yes' COMMENT '是否适用：yes适用/conditional有条件适用' AFTER `biz_type`,
    ADD COLUMN `remark`        VARCHAR(500) NOT NULL DEFAULT '' COMMENT '备注' AFTER `is_applicable`;

-- 清空旧 14 条种子（保留 law_catalog 表结构），替换为完整 88 条清单
DELETE FROM `law_catalog` WHERE `tenant_id`=0;

